      if (merged.strong === true) entry.strong = true
      if (merged.glyph) entry.glyph = merged.glyph
      if (merged.note) entry.note = merged.note
      if (Object.keys(entry).length === 0) delete next[workspaceId]
      else next[workspaceId] = entry
